std::vector<faceted::FacetVertex> makeCloudShell(solar::BodyId id) {
    if(!ice::planet(id)) throw std::runtime_error("Cloud shell requires an ice giant");
    auto dense=mars::makeSampledGlobe(768,[](double,double) { return 0.f; });
    std::vector<faceted::FacetVertex> shell; shell.reserve(dense.indices.size());
    float q=float(ice::polarKm(id)/ice::equatorialKm(id));
    for(auto i:dense.indices) {
        auto p=dense.vertices[i].direction; p.y*=q;
        shell.push_back({p,{255,255,255,255}});
    }
    return shell;
}
bool supports(solar::BodyId id) { return std::find(ids.begin(),ids.end(),id)!=ids.end(); }
int slot(solar::BodyId id) {
    for(int i=0;i<count;++i) if(definitions[i].id==id) return i;
    throw std::runtime_error("Unsupported satellite");
}
const Definition& definition(solar::BodyId id) { return definitions.at(slot(id)); }
std::vector<faceted::FacetVertex> loadSurface(solar::BodyId id,const std::filesystem::path& path,int subdivisions) {
    const auto& d=definition(id);
    if(!d.model) return faceted::makeFacetedGlobe(faceted::loadRgb(path,d.magic,solar::body(id).name),subdivisions);
    std::ifstream in(path,std::ios::binary);
    std::string magic,hash; int version=0; std::size_t count=0;
    if(!(in>>magic>>version>>count>>hash)||magic!=d.magic||version!=1||count==0||count%3||count>2000000||hash.size()!=16||in.get()!='\n')
        throw std::runtime_error("Invalid satellite mesh header: "+path.string());
    std::uint64_t expected=0;
    auto parsed=std::from_chars(hash.data(),hash.data()+hash.size(),expected,16);
    if(parsed.ec!=std::errc{}||parsed.ptr!=hash.data()+hash.size()) throw std::runtime_error("Invalid satellite mesh checksum");
    std::vector<unsigned char> raw(count*16);
    if(!in.read(reinterpret_cast<char*>(raw.data()),std::streamsize(raw.size()))||in.peek()!=EOF) throw std::runtime_error("Satellite mesh length mismatch");
    std::uint64_t hashValue=14695981039346656037ULL;
    for(auto b:raw) { hashValue^=b; hashValue*=1099511628211ULL; }
    if(hashValue!=expected) throw std::runtime_error("Satellite mesh checksum mismatch");
    std::vector<faceted::FacetVertex> mesh(count);
    for(std::size_t i=0;i<count;++i) {
        float xyz[3];
        for(int c=0;c<3;++c) {
            auto p=raw.data()+i*16+c*4;
            std::uint32_t bits=std::uint32_t(p[0])|(std::uint32_t(p[1])<<8)|(std::uint32_t(p[2])<<16)|(std::uint32_t(p[3])<<24);
            std::memcpy(&xyz[c],&bits,4);
            if(!std::isfinite(xyz[c])) throw std::runtime_error("Nonfinite satellite vertex");
        }
        auto& v=mesh[i]; v.direction={xyz[0],xyz[1],xyz[2]};
        float length=mars::dot(v.direction,v.direction);
        if(length<.05f||length>1.0001f) throw std::runtime_error("Satellite vertex outside normalized shape");
        std::copy_n(raw.data()+i*16+12,4,v.color.begin());
        if(v.color[3]!=255) throw std::runtime_error("Invalid satellite opacity");
    }
    for(std::size_t i=0;i<count;i+=3) {
        auto a=mesh[i].direction,b=mesh[i+1].direction,c=mesh[i+2].direction;
        if(mars::dot(mars::cross(b-a,c-a),a)<=0||mesh[i].color!=mesh[i+1].color||mesh[i].color!=mesh[i+2].color)
            throw std::runtime_error("Invalid satellite facet");
    }
    return mesh;
}
const solar::Article& guide(solar::BodyId id) {
    static const auto dimensions=[] {
        std::array<std::array<std::string,2>,7> result;
        for(int i=0;i<7;++i) {
            auto m=solar::saturnianMoons()[i];
            char radius[40],orbit[64];
            std::snprintf(radius,sizeof(radius),"%.2f KM",m.radiusKm);
            std::snprintf(orbit,sizeof(orbit),"%.0f KM FROM SATURN CENTRE",m.orbitKm);
            result[i]={radius,orbit};
        }
        return result;
    }();
    static const auto outerDimensions=[] {
        std::array<std::array<std::string,2>,count> result;
        for(auto parent:{BodyId::Uranus,BodyId::Neptune}) for(const auto& m:solar::outerMoons(parent)) {
            char r[40],o[64]; std::snprintf(r,sizeof(r),"%.2f KM",m.radiusKm);
            std::snprintf(o,sizeof(o),"%.0f KM FROM %s CENTRE",m.orbitKm,solar::body(parent).name);
            result[slot(m.id)]={r,o};
        }
        return result;
    }();
    static const auto articles=[] {
        std::array<solar::Article,count> result;
        for(int i=0;i<count;++i) {
            const auto& d=definitions[i];
            result[i]={solar::body(d.id).name,{d.description},{
                {"PARENT",solar::belts::isDwarf(d.id)?"SUN / HELIOCENTRIC ORBIT":solar::body(solar::body(d.id).parent).name},
                {"SURFACE",(d.id==BodyId::Proteus||d.id>=BodyId::Haumea)?"UNTEXTURED REFERENCE / NO GLOBAL MAP":d.model?"NASA / TEXTURED VISUALIZATION MODEL":"USGS / VOYAGER + GALILEO MOSAIC"},
                {"DISPLAY",d.id==BodyId::Haumea?"ESTIMATED TRIAXIAL ELLIPSOID":(d.id==BodyId::Proteus||d.id>=BodyId::Makemake)?"REFERENCE SPHERE":d.model?"SUPPLIED SHAPE / UNIFORM NORMALIZATION":"MEAN-RADIUS SPHERE / TINTED MONOCHROME"},
                {"COORDINATES",d.model?"MODEL CAMERA ANGLES / NOT GEOGRAPHIC":"PLANETOCENTRIC / EAST LONGITUDE"},
                {"HEIGHT READOUT","NONE / NO CALIBRATED GLOBAL DEM"},
                {"LIGHTING","L / ATLAS LIGHTING OR UNLIT FACETS"},
                {"CONTROLS","DRAG / WHEEL / HOME / 1-4 PRESETS"},
                {"DATA RECOVERY","R / RETRY MISSING OR INVALID ASSET"}
            },"Static mean orbital layout with physical sizes and distances. Outer system tilt nodes are illustrative; positions are not ephemerides. Source hashes and coverage limits: docs/BELTS.md, docs/OUTER_WORLDS.md, docs/SATELLITES.md and docs/SATURN_MOONS.md.",d.source};
        }
        for(int i=0;i<7;++i) {
            const auto& moon=solar::saturnianMoons()[i];
            auto& a=result[slot(moon.id)];
            a.facts.push_back({"MEAN RADIUS",dimensions[i][0].c_str()});
            a.facts.push_back({"MEAN ORBIT",dimensions[i][1].c_str()});
            if(moon.id==BodyId::Titan) a.facts.push_back({"ATMOSPHERE","T / ILLUSTRATIVE HAZE OR SURFACE VIEW"});
        }
        for(auto parent:{BodyId::Uranus,BodyId::Neptune}) for(const auto& m:solar::outerMoons(parent)) {
            int i=slot(m.id); auto& a=result[i];
            a.facts.push_back({"MEAN RADIUS",outerDimensions[i][0].c_str()});
            a.facts.push_back({"MEAN ORBIT",outerDimensions[i][1].c_str()});
        }
        for(auto id:{BodyId::Uranus,BodyId::Neptune}) {
            auto& a=result[slot(id)]; bool u=id==BodyId::Uranus;
            a.facts={{"EQUATOR / POLAR RADIUS",u?"25559 / 24973 KM AT 1 BAR":"24764 / 24341 KM AT 1 BAR"},
                {"REFERENCE ROTATION",u?"17.24 HOURS / RETROGRADE":"16.11 HOURS"},
                {"AXIAL TILT",u?"97.77 DEGREES":"28.32 DEGREES"},
                {"YEAR",u?"84.01 EARTH YEARS":"164.79 EARTH YEARS"},
                {"ATMOSPHERE","HYDROGEN / HELIUM / METHANE"},
                {"CLOUD TOPS","NO SOLID SURFACE / NO ELEVATION"},
                {"SYSTEM SCALE","1 SCENE UNIT = 1,000,000 KM"},
                {"TIME CONTROLS","SPACE / PAUSE; S / SPEED; R / RESET"},
                {"DISPLAY","NASA ARCHIVAL COLOR + ILLUSTRATIVE FLOW"},
                {"RINGS","REFERENCE RADII / ILLUSTRATIVE BRIGHTNESS"}};
            a.note="The reference period is inferred from Voyager magnetic measurements, not the speed of every cloud. The model loop lasts ten rotations. Ring widths and planetary flattening use physical proportions; circular layouts, azimuths, brightness and cloud motion are illustrative. Sources and limitations: docs/OUTER_WORLDS.md.";
        }
        return result;
    }();
    return articles.at(slot(id));
}
const solar::Article& locationGuide(solar::BodyId id,int index) {
    if(index<0||index>=4) throw std::runtime_error("Invalid satellite region");
    static const auto articles=[] {
        std::array<std::array<solar::Article,4>,count> result;
        for(int i=0;i<count;++i) for(int j=0;j<4;++j) {
            const auto& d=definitions[i]; const auto& r=d.regions[j];
            result[i][j]={r.name,{r.notes},{},d.model?"MODEL VIEW / NOT A GEOGRAPHIC LANDMARK":"REGIONAL IMAGE ANCHOR / NO ELEVATION",d.source};
        }
        return result;
    }();
    return articles.at(slot(id)).at(index);
}
